
from slrresearch.agents.technology_extraction_agent import (
    TechnologyExtractionAgent,
)

from slrresearch.schemas.research_question import (
    ResearchQuestion,
)


# Research topic
topic = "Agentic AI in Education"

objective = (
    "Analyze the applications, architectures, roles, "
    "benefits, and challenges of agentic AI in education."
)


# Research questions generated by Agent 1
research_questions = [
    ResearchQuestion(
        id="RQ1",
        question=(
            "What are the primary applications of agentic AI "
            "in educational settings?"
        ),
        rationale="Identify the main educational applications.",
    ),
    ResearchQuestion(
        id="RQ2",
        question=(
            "What architectures and roles do AI agents adopt "
            "in educational systems?"
        ),
        rationale="Study agent architectures and responsibilities.",
    ),
    ResearchQuestion(
        id="RQ3",
        question=(
            "What benefits and challenges are associated "
            "with agentic AI in education?"
        ),
        rationale="Analyze benefits and implementation challenges.",
    ),
]


# Initialize the agent
agent = TechnologyExtractionAgent()


# Execute the agent with real Ollama
response = agent.run(
    topic=topic,
    objective=objective,
    research_questions=research_questions,
)


# Display the result
print("\n========== TECHNOLOGY EXTRACTION RESULT ==========")

print("Status:", response["status"])
print("Repair attempts:", response["repair_attempts"])

print("\nExtracted concepts:")

for concept in response["result"].concepts:
    print("\nConcept:", concept.name)
    print("Category:", concept.category)
    print("Keywords:", concept.keywords)
    print("Related RQs:", concept.related_rqs)

print("\nValidation errors:", response["errors"])
